(2, 'abandoned-cart', 'Abandoned Cart', 'Recover sales by reminding customers about products left in their cart.', 'E-commerce', 'shopping-cart', 'green', 1, 'abandoned_cart', '{\"nodes\":[{\"id\":\"cart_1\",\"type\":\"triggerNode\",\"position\":{\"x\":250,\"y\":50},\"data\":{\"label\":\"Abandoned cart\"}},{\"id\":\"cart_2\",\"type\":\"delayNode\",\"position\":{\"x\":250,\"y\":190},\"data\":{\"label\":\"Wait 1 hour\",\"delayTime\":1,\"delayUnit\":\"hours\"}},{\"id\":\"cart_3\",\"type\":\"emailNode\",\"position\":{\"x\":250,\"y\":330},\"data\":{\"label\":\"Send Cart Reminder\",\"subject\":\"You left something behind!\"}},{\"id\":\"cart_4\",\"type\":\"goalNode\",\"position\":{\"x\":250,\"y\":470},\"data\":{\"label\":\"Made a purchase\",\"conversionValue\":0}}],\"edges\":[{\"id\":\"cart_e1\",\"source\":\"cart_1\",\"target\":\"cart_2\"},{\"id\":\"cart_e2\",\"source\":\"cart_2\",\"target\":\"cart_3\"},{\"id\":\"cart_e3\",\"source\":\"cart_3\",\"target\":\"cart_4\"}]}', '2026-07-21 10:41:58', '2026-07-21 10:41:58'),
(3, 're-engagement', 'Re-engagement', 'Win back inactive subscribers with a targeted message and offer.', 'Retention', 'zap', 'purple', 0, 'tag_added', '{\"nodes\":[{\"id\":\"re_1\",\"type\":\"triggerNode\",\"position\":{\"x\":250,\"y\":50},\"data\":{\"label\":\"Tag added\"}},{\"id\":\"re_2\",\"type\":\"emailNode\",\"position\":{\"x\":250,\"y\":190},\"data\":{\"label\":\"We miss you!\",\"subject\":\"It\'s been a while...\"}}],\"edges\":[{\"id\":\"re_e1\",\"source\":\"re_1\",\"target\":\"re_2\"}]}', '2026-07-21 10:41:58', '2026-07-21 10:41:58'),
(4, 'post-purchase', 'Post-Purchase Follow Up', 'Request a review or recommend related products after a purchase.', 'E-commerce', 'star', 'yellow', 0, 'purchase', '{\"nodes\":[{\"id\":\"post_1\",\"type\":\"triggerNode\",\"position\":{\"x\":250,\"y\":50},\"data\":{\"label\":\"Buys a specific product\"}},{\"id\":\"post_2\",\"type\":\"delayNode\",\"position\":{\"x\":250,\"y\":190},\"data\":{\"label\":\"Wait 7 days\",\"delayTime\":7,\"delayUnit\":\"days\"}},{\"id\":\"post_3\",\"type\":\"emailNode\",\"position\":{\"x\":250,\"y\":330},\"data\":{\"label\":\"Request a review\",\"subject\":\"How do you like your purchase?\"}}],\"edges\":[{\"id\":\"post_e1\",\"source\":\"post_1\",\"target\":\"post_2\"},{\"id\":\"post_e2\",\"source\":\"post_2\",\"target\":\"post_3\"}]}', '2026-07-21 10:41:58', '2026-07-21 10:41:58'),
(5, 'birthday-special', 'Birthday Special', 'Send subscribers a birthday offer to encourage loyalty.', 'Retention', 'gift', 'pink', 0, 'tag_added', '{\"nodes\":[{\"id\":\"birthday_1\",\"type\":\"triggerNode\",\"position\":{\"x\":250,\"y\":50},\"data\":{\"label\":\"Tag added\",\"tag\":\"birthday_today\"}},{\"id\":\"birthday_2\",\"type\":\"emailNode\",\"position\":{\"x\":250,\"y\":190},\"data\":{\"label\":\"Happy Birthday!\",\"subject\":\"A special birthday gift for you\"}},{\"id\":\"birthday_3\",\"type\":\"delayNode\",\"position\":{\"x\":250,\"y\":330},\"data\":{\"label\":\"Wait 3 days\",\"delayTime\":3,\"delayUnit\":\"days\"}},{\"id\":\"birthday_4\",\"type\":\"emailNode\",\"position\":{\"x\":250,\"y\":470},\"data\":{\"label\":\"Offer reminder\",\"subject\":\"Your birthday offer expires soon!\"}}],\"edges\":[{\"id\":\"birthday_e1\",\"source\":\"birthday_1\",\"target\":\"birthday_2\"},{\"id\":\"birthday_e2\",\"source\":\"birthday_2\",\"target\":\"birthday_3\"},{\"id\":\"birthday_e3\",\"source\":\"birthday_3\",\"target\":\"birthday_4\"}]}', '2026-07-21 10:41:58', '2026-07-21 10:41:58'),
