-- --------------------------------------------------------

--
-- Table structure for table `backup_schedules`
--

CREATE TABLE `backup_schedules` (
  `id` int(11) NOT NULL,
  `module_type` varchar(50) NOT NULL DEFAULT 'all',
  `frequency` enum('daily','weekly','monthly','yearly') NOT NULL DEFAULT 'weekly',
  `status` enum('active','paused') NOT NULL DEFAULT 'active',
  `reminder_enabled` tinyint(1) DEFAULT 1,
  `reminder_email` varchar(255) DEFAULT NULL,
  `last_run_at` timestamp NULL DEFAULT NULL,
  `next_run_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `admin_id` int(11) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- --------------------------------------------------------

--
-- Table structure for table `campaigns`
--

CREATE TABLE `campaigns` (
  `id` int(11) NOT NULL,
  `name` varchar(255) NOT NULL,
  `subject` varchar(255) NOT NULL,
  `status` enum('draft','scheduled','sending','sent','submitted_for_review') DEFAULT 'draft',
  `scheduled_at` datetime DEFAULT NULL,
  `html_content` longtext DEFAULT NULL,
  `scheduled_time` datetime DEFAULT NULL,
  `list_id` int(11) DEFAULT NULL,
  `target_email` text DEFAULT NULL,
  `sender_id` varchar(255) DEFAULT NULL,
  `sender_mode` varchar(50) DEFAULT 'broadcast',
  `sender_mapping` longtext DEFAULT NULL CHECK (json_valid(`sender_mapping`)),
  `is_ab_test` tinyint(1) DEFAULT 0,
  `variant_b_subject` varchar(255) DEFAULT NULL,
  `variant_b_html` longtext DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `sender_history` text DEFAULT NULL,
  `admin_id` int(11) DEFAULT NULL,
  `admin_email` varchar(255) DEFAULT NULL,
  `domain_name` varchar(255) DEFAULT NULL,
  `smtp_id` int(11) DEFAULT NULL,
  `smtp_email` varchar(255) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Dumping data for table `campaigns`
