rent_timestamp(),\\n  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),\\n  PRIMARY KEY (`id`),\\n  KEY `list_id` (`list_id`),\\n  CONSTRAINT `campaigns_ibfk_1` FOREIGN KEY (`list_id`) REFERENCES `lists` (`id`) ON DELETE SET NULL\\n) ENGINE=InnoDB AUTO_INCREMENT=41 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;\\n\\nINSERT INTO `campaigns` (`id`, `name`, `subject`, `status`, `scheduled_at`, `html_content`, `scheduled_time`, `list_id`, `target_email`, `sender_id`, `is_ab_test`, `variant_b_subject`, `variant_b_html`, `created_at`, `updated_at`) VALUES \\n(6, \'New Compaign\', \'Subject  Variant A\', \'sent\', NULL, \'<!DOCTYPE HTML PUBLIC \\\"-//W3C//DTD XHTML 1.0 Transitional //EN\\\" \\\"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\\\">\\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" xmlns:v=\\\"urn:schemas-microsoft-com:vml\\\" xmlns:o=\\\"urn:schemas-microsoft-com:office:office\\\">\\n<head>\\n<!--[if gte mso 9]>\\n<xml>\\n  <o:OfficeDocumentSettings>\\n    <o:AllowPNG/>\\n    <o:PixelsPerInch>96</o:PixelsPerInch>\\n  </o:OfficeDocumentSettings>\\n</xml>\\n<![endif]-->\\n  <meta http-equiv=\\\"Content-Type\\\" content=\\\"text/html; charset=UTF-8\\\">\\n  <meta name=\\\"viewport\\\" content=\\\"width=device-width, initial-scale=1.0\\\">\\n  <meta name=\\\"x-apple-disable-message-reformatting\\\">\\n  <!--[if !mso]><!--><meta http-equiv=\\\"X-UA-Compatible\\\" content=\\\"IE=edge\\\"><!--<![endif]-->\\n  \\n  \\n    <style type=\\\"text/css\\\">\\n      \\n      @media only screen and (min-width: 520px) {\\n        .u-row {\\n          width: 500px !important;\\n        }\\n\\n        .u-row .u-col {\\n          vertical-align: top;\\n        }\\n\\n        \\n            .u-row .u-col-100 {\\n              width: 500px !important;\\n            }\\n          \\n      }\\n\\n      @media only screen and (max-width: 520px) {\\n        .u-row-container {\\n          max-width: 100% !important;\\n          pa