(11, 'Manual AUTOMATIONS Backup - 03/08/2026', '{\"automations\":\"DROP TABLE IF EXISTS `automations`;\\nCREATE TABLE `automations` (\\n  `id` int(11) NOT NULL AUTO_INCREMENT,\\n  `name` varchar(255) NOT NULL,\\n  `trigger_type` varchar(100) NOT NULL,\\n  `workflow_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`workflow_json`)),\\n  `status` enum(\'draft\',\'active\',\'paused\',\'stopped\',\'completed\',\'archived\',\'error\') DEFAULT \'draft\',\\n  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),\\n  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),\\n  `audience_id` int(11) DEFAULT NULL,\\n  `reentry_policy` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`reentry_policy`)),\\n  PRIMARY KEY (`id`)\\n) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;\\n\\nINSERT INTO `automations` (`id`, `name`, `trigger_type`, `workflow_json`, `status`, `created_at`, `updated_at`, `audience_id`, `reentry_policy`) VALUES \\n(1, \'Workflow Name\', \'welcome\', \'{\\\"steps\\\":[{\\\"id\\\":1,\\\"type\\\":\\\"trigger\\\",\\\"description\\\":\\\"When someone subscribes\\\"}]}\', \'active\', \'\\\"2026-07-14T07:43:49.000Z\\\"\', \'\\\"2026-07-14T11:21:35.000Z\\\"\', NULL, NULL),\\n(3, \'vimal\', \'welcome\', \'{\\\"steps\\\":[{\\\"id\\\":1,\\\"type\\\":\\\"trigger\\\",\\\"description\\\":\\\"When someone subscribes\\\"}]}\', \'draft\', \'\\\"2026-07-15T12:24:25.000Z\\\"\', \'\\\"2026-07-15T12:24:25.000Z\\\"\', NULL, NULL),\\n(4, \'Re-engagement\', \'template\', \'{\\\"nodes\\\":[{\\\"id\\\":\\\"example_trigger\\\",\\\"type\\\":\\\"triggerNode\\\",\\\"position\\\":{\\\"x\\\":340,\\\"y\\\":40},\\\"data\\\":{\\\"label\\\":\\\"Subscriber joins list\\\"},\\\"measured\\\":{\\\"width\\\":240,\\\"height\\\":106}},{\\\"id\\\":\\\"example_welcome\\\",\\\"type\\\":\\\"emailNode\\\",\\\"position\\\":{\\\"x\\\":340,\\\"y\\\":180},\\\"data